cd /bench/repo
find . -name '*.go' -not -path './web/*' | xargs awk '
FNR==1 { fn="<file-scope>"; pkg="" }
/^package / { pkg=$2 }
/^func / {
  line=$0
  sub(/^func +/,"",line)
  if (substr(line,1,1)=="(") { sub(/^\([^)]*\) */,"",line) }
  match(line,/^[A-Za-z_][A-Za-z0-9_]*/)
  fn=substr(line,RSTART,RLENGTH)
  next
}
{
  s=$0
  sub(/\/\/.*/,"",s)
  while (match(s, /[A-Za-z_][A-Za-z0-9_]*\(/)) {
    tok=substr(s,RSTART,RLENGTH-1)
    pre=(RSTART>1)?substr(s,RSTART-1,1):" "
    qual=(pre==".")?"Q":"U"
    print tok"\t"qual"\t"pkg"\t"FILENAME"\t"fn
    s=substr(s,RSTART+RLENGTH)
  }
}' > /tmp/calls.tsv
wc -l /tmp/calls.tsv

cd /bench/repo
find . -name '*.go' -not -path './web/*' | xargs awk '
FNR==1 { fn="<file-scope>" }
/^package / { pkg=$2 }
/^func / { line=$0; sub(/^func +/,"",line); if(substr(line,1,1)=="(") sub(/^\([^)]*\) */,"",line)
  match(line,/^[A-Za-z_][A-Za-z0-9_]*/); fn=substr(line,RSTART,RLENGTH); next }
{ s=$0; sub(/\/\/.*/,"",s)
  while (match(s, /([A-Za-z_][A-Za-z0-9_]*\.)?[A-Za-z_][A-Za-z0-9_]*\(/)) {
    full=substr(s,RSTART,RLENGTH-1)
    pre=(RSTART>1)?substr(s,RSTART-1,1):" "
    if (pre!=".") print full"\t"pkg"\t"FILENAME"\t"fn
    s=substr(s,RSTART+RLENGTH)
  } }' > /tmp/calls2.tsv
echo "=== qualified calls into internal packages (distinct callers) ==="
awk -F'\t' '$1 ~ /\./ { split($1,a,"."); key=$1 SUBSEP $3 SUBSEP $4; if(!(k[key]++)) c[$1]++ }
END{for(n in c) print c[n]"\t"n}' /tmp/calls2.tsv | sort -rn | head -40

cd /bench/repo
# Build: for each symbol declared in internal/, its package name + dir
grep -rn "^func " --include=*.go internal/ | awk -F: '{
  f=$1; line=$0; sub(/^[^:]*:[0-9]+:func +/,"",line)
  if(substr(line,1,1)=="(") sub(/^\([^)]*\) */,"",line)
  match(line,/^[A-Za-z_][A-Za-z0-9_]*/); nm=substr(line,RSTART,RLENGTH)
  d=f; sub(/\/[^\/]*$/,"",d)
  print nm"\t"d"\t"f
}' | sort -u > /tmp/decls2.tsv
# pkg name per dir
for d in $(find internal -name '*.go' | xargs -n1 dirname | sort -u); do
  p=$(grep -h "^package " $d/*.go 2>/dev/null | head -1 | awk '{print $2}')
  echo -e "$d\t$p"
done > /tmp/pkgdir.tsv

awk -F'\t' '
NR==FNR { pkgof[$1]=$2; next }
FILENAME=="/tmp/decls2.tsv" { dir[$1"\t"$2]=1; decldir[$1]=decldir[$1]" "$2; next }
{ # calls2: full, pkg, file, fn
  full=$1; caller=$3"\t"$4
  if (index(full,".")) { split(full,a,"."); q=a[1]; nm=a[2] } else { q=""; nm=full }
  cd=$3; sub(/\/[^\/]*$/,"",cd)
  n=split(decldir[nm],ds," ")
  for(i=1;i<=n;i++){ d=ds[i]
    ok=0
    if (q=="" && cd==d) ok=1            # same-dir unqualified
    else if (q!="" && q==pkgof[d]) ok=1 # package-qualified
    if(ok){ k=nm"\t"d"\t"caller; if(!(k in seen)){seen[k]=1; if($4!=nm) c[nm"\t"d]++} }
  }
}
END{for(x in c) print c[x]"\t"x}' /tmp/pkgdir.tsv /tmp/decls2.tsv /tmp/calls2.tsv | sort -rn | head -25

cd /bench/repo
sed -i 's#\t\./#\t#' /tmp/calls2.tsv
# decls with recv flag
grep -rn "^func " --include=*.go internal/ | awk -F: '{
  f=$1; line=$0; sub(/^[^:]*:[0-9]+:func +/,"",line)
  recv=0; if(substr(line,1,1)=="("){recv=1; sub(/^\([^)]*\) */,"",line)}
  match(line,/^[A-Za-z_][A-Za-z0-9_]*/); nm=substr(line,RSTART,RLENGTH)
  d=f; sub(/\/[^\/]*$/,"",d); print nm"\t"d"\t"recv
}' | sort -u > /tmp/decls3.tsv

echo "===== PLAIN FUNCTIONS (package-qualified or same-package) ====="
awk -F'\t' '
NR==FNR{pkgof[$1]=$2;next}
FILENAME=="/tmp/decls3.tsv"{ if($3=="0"){fdir[$1]=fdir[$1]" "$2} ; next}
{ full=$1; caller=$3"\t"$4; cd=$3; sub(/\/[^\/]*$/,"",cd)
  if(index(full,".")){split(full,a,"."); q=a[1]; nm=a[2]} else {q="";nm=full}
  n=split(fdir[nm],ds," ")
  for(i=1;i<=n;i++){d=ds[i]; ok=0
    if(q==""&&cd==d)ok=1; else if(q!=""&&q==pkgof[d])ok=1
    if(ok){k=nm"\t"d"\t"caller; if(!(k in seen)){seen[k]=1; if($4!=nm)c[nm"\t"d]++}}}}
END{for(x in c)print c[x]"\t"x}' /tmp/pkgdir.tsv /tmp/decls3.tsv /tmp/calls2.tsv | sort -rn | head -12

echo "===== METHODS (any receiver.Name call, name-collision-prone) ====="
awk -F'\t' '
FILENAME=="/tmp/decls3.tsv"{ if($3=="1")mdir[$1]=mdir[$1]" "$2; next}
{ full=$1; if(!index(full,"."))next; split(full,a,"."); nm=a[2]
  if(!(nm in mdir))next
  k=nm"\t"$3"\t"$4; if(!(k in seen)){seen[k]=1; if($4!=nm)c[nm]++}}
END{for(x in c)print c[x]"\t"x"\t"mdir[x]}' /tmp/decls3.tsv /tmp/calls2.tsv | sort -rn | head -12

